CREATE TABLE IF NOT EXISTS public.light_forge_recipes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), input_tier text NOT NULL, output_tier text NOT NULL, input_count integer NOT NULL DEFAULT 3, camly_cost integer NOT NULL, xp_reward integer NOT NULL DEFAULT 200, output_collection text NOT NULL DEFAULT 'light_spark', echo_chance numeric NOT NULL DEFAULT 0.05, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (input_tier, output_tier)); ALTER TABLE public.light_forge_recipes ENABLE ROW LEVEL SECURITY; CREATE POLICY "forge_recipes_public_read" ON public.light_forge_recipes FOR SELECT USING (true);